// HostServer is the server API for Host service.
// All implementations must embed UnimplementedHostServer
// for forward compatibility.
//
// Host exposes permission-checked capabilities on a connection bound to one plugin installation.
type HostServer interface {
	// GetSiteInfo reads public site presentation context without requiring a permission.
	GetSiteInfo(context.Context, *GetSiteInfoRequest) (*SiteInfo, error)
	// GetUser reads an account with user.read; user.email separately permits the email field.
	GetUser(context.Context, *GetUserRequest) (*User, error)
	// LookupUsers performs exact account searches with user.lookup and additionally user.email for email searches.
	LookupUsers(context.Context, *LookupUsersRequest) (*LookupUsersResponse, error)
	// ListUserIdentities reads sanitized identity bindings with the user.identities permission.
	ListUserIdentities(context.Context, *ListUserIdentitiesRequest) (*ListUserIdentitiesResponse, error)
	// GetWallet reads balance and cumulative recharge with the wallet.read permission.
	GetWallet(context.Context, *GetWalletRequest) (*Wallet, error)
	// WalletCredit credits a positive amount with wallet.credit and an idempotency key.
	WalletCredit(context.Context, *WalletRequest) (*WalletResponse, error)
	// WalletDebit debits a positive amount with wallet.debit and a matching unexpired caller grant.
	WalletDebit(context.Context, *WalletRequest) (*WalletResponse, error)
	// IssueRedeemCode issues one redeem code with redeem.issue and a plugin-wide idempotency key.
	IssueRedeemCode(context.Context, *IssueRedeemCodeRequest) (*IssueRedeemCodeResponse, error)
	// ListSubscriptionPlans reads offered plans with the subscription.read permission.
	ListSubscriptionPlans(context.Context, *ListSubscriptionPlansRequest) (*ListSubscriptionPlansResponse, error)
	// ListUserSubscriptions reads account subscriptions with the subscription.read permission.
	ListUserSubscriptions(context.Context, *ListUserSubscriptionsRequest) (*ListUserSubscriptionsResponse, error)
	// GrantSubscription issues approved-plan subscriptions with subscription.grant and an idempotency key.
	GrantSubscription(context.Context, *GrantSubscriptionRequest) (*GrantSubscriptionResponse, error)
	// GetUsageSummary reads caller usage with usage.self and a grant, or arbitrary account usage with usage.read.
	GetUsageSummary(context.Context, *GetUsageSummaryRequest) (*UsageSummary, error)
	// GetUsageStats reads bounded account aggregates with the usage.read permission.
	GetUsageStats(context.Context, *GetUsageStatsRequest) (*GetUsageStatsResponse, error)
	// GetUsageRanking reads bounded rankings with the usage.read permission.
	GetUsageRanking(context.Context, *GetUsageRankingRequest) (*GetUsageRankingResponse, error)
	// ListUserOrders reads sanitized account orders with the payment.read permission.
	ListUserOrders(context.Context, *ListUserOrdersRequest) (*ListUserOrdersResponse, error)
	// ListModels returns the public marketplace JSON with the catalog.read permission.
	ListModels(context.Context, *ListModelsRequest) (*ListModelsResponse, error)
	// ListUserGroups reads effective account groups with the catalog.read permission.
	ListUserGroups(context.Context, *ListUserGroupsRequest) (*ListUserGroupsResponse, error)
	// SendEmail sends plain-text notifications with notify.email; unknown delivery outcomes are not automatically resent.
	SendEmail(context.Context, *SendEmailRequest) (*SendEmailResponse, error)
	// VerifyCaptcha checks the site captcha with captcha.verify using the forwarded client address.
	VerifyCaptcha(context.Context, *VerifyCaptchaRequest) (*VerifyCaptchaResponse, error)
	// KVGet reads an unexpired key in the calling plugin namespace without additional permissions.
	KVGet(context.Context, *KVGetRequest) (*KVGetResponse, error)
	// KVPut writes JSON with an atomic version condition in the calling plugin namespace.
	KVPut(context.Context, *KVPutRequest) (*KVPutResponse, error)
	// KVDelete deletes a key with an optional atomic version condition in the calling plugin namespace.
	KVDelete(context.Context, *KVDeleteRequest) (*KVDeleteResponse, error)
	// KVList lists unexpired keys in ascending order within the calling plugin namespace.
	KVList(context.Context, *KVListRequest) (*KVListResponse, error)
	// KVIncr atomically changes an integer key in the calling plugin namespace.
	KVIncr(context.Context, *KVIncrRequest) (*KVIncrResponse, error)
	mustEmbedUnimplementedHostServer()
}

